-- Claude Code — RMB/USD TEK KAYNAK + maliyet Excel'i 335 ürün düzeltmesi (2026-10-10). Alperen: "Maliyet Excel'i için açık kural RMB/USD = 6,7 idi;
-- PR #248 üretimde 6,8 kullanmış ... 6,7 esas alınarak ... kontrollü düzelt".
-- 1) Tek kaynak: MonthlyExchangeRate 2026-10 (RMB/USD 6,7; USD/TRY 48,98 = cfo_kur 2026-10). lib/fx/current.ts RMB'yi YALNIZ buradan okur
--    (cfo_settings.usdRmbRate 6,72 ve kod sabitleri 7,2/7,0 kaldırıldı). Kayıt zaten varsa işlem iptal.
-- 2) 335 ürün: unitCostUsd/unitCostTry = calcImportCost (RMB/6,7 × 1,05 + motorun seçtiği navlun + GTİP gümrüğü) × 48,98 — lib/cfo/cost-derivation.ts ile
--    üretim verisinden türetildi. Gümrük % değişmez. Eşzamanlılık korumalı (USD ve TL okunan eski değerdeyse); 335'in tamamı yazılmazsa işlem iptal.
--    Her alan cfo_change_log'a (eski → yeni), özet satırı. Ölçüm (öncesi, salt-okunur): LCNRV +7.405,67 TL → net sermaye +7.405,67 TL.
BEGIN;
DO $g$ BEGIN
  IF EXISTS (SELECT 1 FROM public."MonthlyExchangeRate" WHERE year = 2026 AND month = 10) THEN RAISE EXCEPTION 'MonthlyExchangeRate 2026-10 zaten var'; END IF;
END $g$;
INSERT INTO public."MonthlyExchangeRate" (id, year, month, "usdTryRate", "rmbUsdRate", note, "createdAt", "updatedAt")
VALUES (gen_random_uuid()::text, 2026, 10, 48.98, 6.7, 'RMB/USD 6,7 — Alperen kuralı (maliyet Excel''i), CFO maliyeti tek kaynak; USD/TRY = cfo_kur 2026-10', now(), now());
INSERT INTO public.cfo_change_log (id, area, item, "oldValue", "newValue", source, kind, note)
VALUES (gen_random_uuid()::text, 'kural', 'RMB/USD tek kaynak (MonthlyExchangeRate 2026-10)', '6.8 (elle 2026-06; ayrıca cfo_settings 6.72, kod yedeği 7.2)', '6.7', 'Alperen (RMB/USD 6,7 kuralı) + Claude Code', 'karar',
  'CFO maliyeti, ithalatçı görünümü ve CFO-029 RMB/USD''yi yalnız MonthlyExchangeRate''ten okur; kur yoksa maliyet hesaplanmaz (sabit yedek yok).');
