CREATE TEMP TABLE _u ON COMMIT DROP AS SELECT sku FROM _v WHERE false;
WITH u AS (
  UPDATE public."Product" p SET "unitCostUsd" = v.nu::numeric, "unitCostTry" = v.nt::numeric, "updatedAt" = now()
    FROM _v v
   WHERE p.sku = v.sku AND p."unitCostUsd" IS NOT DISTINCT FROM v.ou::numeric AND p."unitCostTry" IS NOT DISTINCT FROM v.ot::numeric
  RETURNING p.sku)
INSERT INTO _u SELECT sku FROM u;
DO $g$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM _u; IF n <> 335 THEN RAISE EXCEPTION 'koruma: % / 335 ürün yazılabildi', n; END IF; END $g$;
INSERT INTO public.cfo_change_log (id, area, item, "oldValue", "newValue", source, kind, note)
SELECT gen_random_uuid()::text, 'maliyet', v.sku || ' ' || x.alan, x.o, x.n, 'Alperen (RMB/USD 6,7 kuralı) + Claude Code', 'duzeltme', 'RMB/USD 6,8 → 6,7 (Alperen kuralı; tek kaynak MonthlyExchangeRate 2026-10). İthalat motoru (calcImportCost): RMB/6,7 × 1,05 + motorun seçtiği navlun + GTİP gümrüğü (değişmedi); USD/TRY 48,98 (cfo_kur 2026-10). Kayıt: docs/maliyet/2026-10-10-rmb-6-7-tek-kaynak.md'
  FROM _v v CROSS JOIN LATERAL (VALUES ('unitCostUsd', v.ou, v.nu), ('unitCostTry', v.ot, v.nt)) x(alan, o, n);
INSERT INTO public.cfo_change_log (id, area, item, "oldValue", "newValue", source, kind, note)
VALUES (gen_random_uuid()::text, 'maliyet', 'RMB/USD 6,7 düzeltmesi özeti (maliyet Excel''i 335 ürün)', NULL, '335 ürün, 670 alan', 'Alperen (RMB/USD 6,7 kuralı) + Claude Code', 'analiz',
